   return subtotalCents - Math.round((subtotalCents * percent) / 100);
 }
+
+// A fixed-amount coupon never takes the subtotal below zero.
+export function amountOff(subtotalCents, offCents) {
+  if (!Number.isInteger(offCents) || offCents < 0) throw new RangeError(`offCents must be a non-negative integer: ${offCents}`);
+  return Math.max(0, subtotalCents - offCents);
